const ids=new Set(LEARNING_TOPICS.map(t=>t.id)),phases=new Set(['welcome','sound','practice','expedition','play','return','upgrade','done']);
export const topicById=id=>LEARNING_TOPICS.find(t=>t.id===id)||null;
export const learningAccount=s=>s?.accountScore?.id||null;
export function initialLearning(profile,{fresh=false}={}){return {version:1,accountId:learningAccount(profile),phase:fresh?'welcome':profile.tutorialIntro?.eligibility==='eligible'&&profile.level===1?(profile.run?'play':hasCampaignReturn(profile)?'return':'expedition'):'done',paused:false,guideOpened:false,seen:profile.journey?.relicIntroDone?['reliquary']:[],deferred:[],pending:[],available:LEARNING_TOPICS.filter(t=>t.eligible(profile)).map(t=>t.id),baseLevel:profile.level,milestones:{practiceStarted:false,practiceVisited:false,firstAction:false,firstMineral:false,firstExpedition:false,firstClear:false,firstReturn:false,firstUpgrade:profile.level>1}};}
export function restoreLearning(raw,profile,{fresh=false}={}){
 const initial=initialLearning(profile,{fresh});if(!raw||raw.version!==1||raw.accountId!==initial.accountId||!phases.has(raw.phase))return initial;
 const list=key=>[...new Set((Array.isArray(raw[key])?raw[key]:[]).filter(id=>ids.has(id)))];
 return {...initial,phase:raw.phase,paused:raw.paused===true,guideOpened:raw.guideOpened===true,baseLevel:Number.isSafeInteger(raw.baseLevel)&&raw.baseLevel>=1?raw.baseLevel:initial.baseLevel,seen:list('seen'),deferred:list('deferred'),pending:list('pending'),available:list('available'),milestones:Object.fromEntries(Object.keys(initial.milestones).map(k=>[k,raw.milestones?.[k]===true]))};
}
// Separate learning state: this class never writes the gameplay profile.
export class LearningPath{
 constructor(profile,raw,options){this.record=restoreLearning(raw,profile,options);}
 enqueue(id,profile){const r=this.record,t=topicById(id);if(!t||!t.eligible(profile)||r.seen.includes(id)||r.deferred.includes(id)||r.pending.includes(id))return false;r.pending.push(id);return true;}
 observe(profile){const r=this.record,before=JSON.stringify(r),available=LEARNING_TOPICS.filter(t=>t.eligible(profile)).map(t=>t.id);for(const id of available)if(!r.available.includes(id)&&topicById(id).unlock)this.enqueue(id,profile);r.available=available;
  if(profile.level>r.baseLevel){r.milestones.firstUpgrade=true;if(['upgrade','return','practice'].includes(r.phase))r.phase='done';}
  if(profile.run&&profile.run.mode!=='abyss'&&!profile.run.trainingClock&&!['done','upgrade'].includes(r.phase))r.phase='play';
  if(hasCampaignReturn(profile)&&!r.milestones.firstReturn){r.milestones.firstReturn=true;if(!['done','upgrade'].includes(r.phase))r.phase=r.milestones.firstUpgrade?'done':'return';}
  if(profile.run?.room.cleared&&!profile.run.cardChosen)this.enqueue('cards',profile);
  if(profile.run&&profile.run.mode!=='abyss'&&!profile.run.trainingClock)r.milestones.firstExpedition=true;
  if(profile.run&&Object.values(profile.run.items||{}).some(n=>n>0))this.enqueue('items',profile);
  return before!==JSON.stringify(r);
 }
 events(events,profile){const before=JSON.stringify(this.record);for(const e of Array.isArray(events)?events:[]){if(profile.run&&profile.run.mode!=='abyss'&&!profile.run.trainingClock){if(e?.type==='perfect')this.record.milestones.firstAction=true;if(e?.type==='loot'&&e.value>0&&profile.run.loot?.crystals?.some(c=>c.gems>0))this.record.milestones.firstMineral=true;}if(e?.type==='clear'&&profile.run&&profile.run.mode!=='abyss'&&!profile.run.trainingClock){this.record.milestones.firstClear=true;}const id={levelUp:'tree',petUnlocked:'pets',recordDrop:'records',orbPurchase:'orbs',minibossNearby:'sentinel',minibossEngaged:'sentinel',missionReady:'mission-ready',missionExpired:'missions',recovery:'breath',rest:'camp',bossWarning:'boss',bossDefeated:'boss',findChest:'discoveries',card:'cards'}[e?.type];if(id)this.enqueue(id,profile);if(e?.type==='hurt'&&e.reserve==='rhythm')this.enqueue('breath',profile);if(e?.type==='perfect'&&e.combo>=5)this.enqueue('combo',profile);if(e?.type==='proc'&&e.id==='find-chest')this.enqueue('discoveries',profile);}this.observe(profile);return before!==JSON.stringify(this.record);}
 opened(page,profile){for(const topic of LEARNING_TOPICS)if(topic.pages.includes(page))this.enqueue(topic.id,profile);}
 seen(id){const r=this.record;if(!ids.has(id))return;if(!r.seen.includes(id))r.seen.push(id);r.pending=r.pending.filter(x=>x!==id);r.deferred=r.deferred.filter(x=>x!==id);}
 defer(id){const r=this.record;if(ids.has(id)&&!r.deferred.includes(id))r.deferred.push(id);r.pending=r.pending.filter(x=>x!==id);}
 practiceStarted(){this.record.phase='practice';this.record.milestones.practiceStarted=true;}
 practiceFinished(){this.record.phase=['welcome','sound','practice'].includes(this.record.phase)?'expedition':this.record.phase;this.record.milestones.practiceVisited=true;}
 next(profile){const r=this.record;if(r.paused)return null;if(['welcome','sound','practice','expedition','return'].includes(r.phase))return r.phase;if(r.phase==='upgrade'&&!r.seen.includes('forge'))return 'forge';return r.pending.find(id=>topicById(id)?.eligible(profile))||null;}
}
